sys_transform_script.script:
(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {
    // Validate that required fields are present
    if (!source.name || source.name.toString().trim() === '') {
        log.error('Honda Import: Name is required and cannot be empty');
        return;
    }

    // Basic mobile number validation (optional field)
    if (source.mobile_number && source.mobile_number.toString().trim() !== '') {
        var mobileRegex = /^[+]?[0-9\s\-\(\)]+$/;
        if (!mobileRegex.test(source.mobile_number.toString().trim())) {
            log.error('Honda Import: Invalid mobile number format: ' + source.mobile_number);
            return;
        }
    }

    log.info('Honda Import: Processing user - ' + source.name);

})(source, map, log, target);
